SINA_SMART["physio1-cardiac-cycle"] = {"lecture":"physio1-cardiac-cycle","title":"The cardiac cycle and cardiac output","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-cardiac-cycle:e0","text":"Cycle = systole (contraction, ejection) + diastole (relaxation, filling).","topic":"The cardiac cycle and heart sounds","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiac-cycle:e1","text":"S1: AV valves close; S2: semilunar valves close.","topic":"The cardiac cycle and heart sounds","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiac-cycle:e2","text":"Murmur = turbulent flow; incompetent (leaky) vs stenotic (narrow) valve.","topic":"The cardiac cycle and heart sounds","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiac-cycle:e4","text":"CO = HR × SV ≈ 70 × 70 ≈ 5 L/min; 20-30 L/min in exercise.","topic":"Cardiac output and heart rate","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiac-cycle:e5","text":"Chronotropic: sympathetic ↑, parasympathetic ↓.","topic":"Cardiac output and heart rate","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiac-cycle:e3","text":"Systolic: MR, AS; diastolic: MS, AR.","topic":"Stroke volume, Starling's law and ejection fraction","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiac-cycle:e6","text":"SV = EDV − ESV ≈ 70 mL.","topic":"Stroke volume, Starling's law and ejection fraction","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiac-cycle:e7","text":"Starling: ↑ preload (venous return, EDV) → ↑ SV.","topic":"Stroke volume, Starling's law and ejection fraction","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiac-cycle:e8","text":"Sympathetic and thyroid hormones ↑ contractility → ↓ ESV.","topic":"Stroke volume, Starling's law and ejection fraction","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-cardiac-cycle:e9","text":"EF = SV / EDV; normal 50-75%.","topic":"Stroke volume, Starling's law and ejection fraction","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"10re2ux":"a","13hh7k":"a","y96fde":"a","1ycsnh4":"a","1cpqrvn":"a","1pb7mv8":"a","1md4hiz":"a","16oaqwq":"a","1susj0e":"a","8hoqvr":"a","13ecnpc":"a","12n6isb":"a","1x3upu1":"a","q3b7h9":"a","dfcdur":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-cardiac-cycle:e0":{"s":0,"u":["Cycle = systole (contraction, ejection) + diastole (relaxation, filling).","The cardiac cycle is all the events of one heartbeat: systole (contraction, ejection of blood) and diastole (relaxation, filling)."],"dp":[{"h":"Why a failing heart gets bigger","t":"When contractility falls, the ventricle ejects less, so more blood remains at the end of systole and filling raises the end-diastolic volume. By Starling's law the extra stretch restores some force, and stroke volume is partly maintained, but at the price of a dilated ventricle and a falling ejection fraction. Beyond the optimum length the curve flattens and then drops: more filling only raises pressures, backing blood up into the lungs (breathlessness) or veins (oedema). An EF well below 50% on an echocardiogram is how this is measured in the clinic. Source: the lecture's Frank-Starling curve, over-extension note and ejection fraction."}]},"physio1-cardiac-cycle:e1":{"s":0,"u":["S1: AV valves close; S2: semilunar valves close.","In diastole the atrioventricular valves are open and the ventricles fill, completed by atrial contraction; in systole the ventricles contract, the AV valves close ( first heart sound, S1 ), pressure rises until the semilunar valves open and blood is ejected; as the ventricles relax, the aortic and pulmonary valves close ( second sound, S2 ).","An incompetent (regurgitant) valve does not close fully and gives a swishing sound; a stenotic valve does not open fully and gives a high-pitched sound or click."],"dp":[]},"physio1-cardiac-cycle:e2":{"s":0,"u":["Murmur = turbulent flow; incompetent (leaky) vs stenotic (narrow) valve.","Murmurs are abnormal sounds from turbulent flow ; in adults most come from valves.","An incompetent (regurgitant) valve does not close fully and gives a swishing sound; a stenotic valve does not open fully and gives a high-pitched sound or click."],"dp":[]},"physio1-cardiac-cycle:e4":{"s":1,"u":["CO = HR × SV ≈ 70 × 70 ≈ 5 L/min; 20-30 L/min in exercise.","Cardiac output (CO) is the volume pumped by each ventricle per minute: CO = heart rate × stroke volume , about 70 beats/min × 70 mL ≈ 5 L/min at rest and 20-30 L/min in exercise."],"dp":[]},"physio1-cardiac-cycle:e5":{"s":1,"u":["Chronotropic: sympathetic ↑, parasympathetic ↓.","Factors that raise heart rate are positive chronotropic , those that lower it negative chronotropic .","The sympathetic system (noradrenaline) increases heart rate and innervates both nodes and muscle; the parasympathetic (acetylcholine, vagus) decreases it and innervates mainly the nodes."],"dp":[]},"physio1-cardiac-cycle:e3":{"s":2,"u":["Systolic: MR, AS; diastolic: MS, AR.","Stroke volume = end-diastolic volume − end-systolic volume (SV = EDV − ESV); at rest about 70 mL , roughly 60% of the ventricular content."],"dp":[]},"physio1-cardiac-cycle:e6":{"s":2,"u":["SV = EDV − ESV ≈ 70 mL.","Lecture example: rest EDV 135, ESV 65 → SV 70 mL; Frank-Starling alone (EDV 165) → SV 100 mL; sympathetic alone (ESV 35) → SV 100 mL; both → SV 130 mL.","Stroke volume = end-diastolic volume − end-systolic volume (SV = EDV − ESV); at rest about 70 mL , roughly 60% of the ventricular content."],"dp":[]},"physio1-cardiac-cycle:e7":{"s":2,"u":["Starling: ↑ preload (venous return, EDV) → ↑ SV.","Starling's law : the critical factor controlling stroke volume is preload , the stretch of the fibres before contraction, set mainly by venous return and hence EDV.","It depends on preload , contractility and afterload."],"dp":[]},"physio1-cardiac-cycle:e8":{"s":2,"u":["Sympathetic and thyroid hormones ↑ contractility → ↓ ESV.","Extrinsic controls : sympathetic noradrenaline on β1 receptors and hormones such as thyroid hormones increase the force of contraction, so the ventricle empties further (lower ESV).","The ejection fraction , EF = SV / EDV, normally 50-75% at rest, is a measure of contractility; increased contractility raises it."],"dp":[]},"physio1-cardiac-cycle:e9":{"s":2,"u":["EF = SV / EDV; normal 50-75%.","A slow heart rate or exercise raises EDV."],"dp":[]}},"meta":{"10re2ux":{"a":"recall","vg":"physio1-cardiac-cycle:e0/recall/1"},"13hh7k":{"a":"relationship","vg":"physio1-cardiac-cycle:e1/relationship/1"},"y96fde":{"a":"relationship","vg":"physio1-cardiac-cycle:e2/relationship/1"},"1ycsnh4":{"a":"recall","vg":"physio1-cardiac-cycle:e0/recall/2"},"1cpqrvn":{"a":"recall","vg":"physio1-cardiac-cycle:e0/recall/2"},"1pb7mv8":{"a":"recall","vg":"physio1-cardiac-cycle:e4/recall/1"},"1md4hiz":{"a":"recall","vg":"physio1-cardiac-cycle:e4/recall/2"},"16oaqwq":{"a":"recall","vg":"physio1-cardiac-cycle:e6/recall/1"},"1susj0e":{"a":"recall","vg":"physio1-cardiac-cycle:e7/recall/1"},"8hoqvr":{"a":"recall","vg":"physio1-cardiac-cycle:e7/recall/2"},"13ecnpc":{"a":"recall","vg":"physio1-cardiac-cycle:e6/recall/2"},"12n6isb":{"a":"recall","vg":"physio1-cardiac-cycle:e9/recall/1"},"1x3upu1":{"a":"recall","vg":"physio1-cardiac-cycle:e6/recall/1"},"q3b7h9":{"a":"recall","vg":"physio1-cardiac-cycle:e5/recall/1"},"dfcdur":{"a":"application","vg":"physio1-cardiac-cycle:e4/application/1"}},"explRev":"c91770b8ac7f"};
